const P=k=>PS[k];
/* [skill, passage, the question, the right choice, two wrong choices, why] */
const ROWS=[
 ['evidence','mara','Which sentence is the best evidence for the claim that Mara is waiting nervously for something?','Mara checked the clock for the third time in ten minutes and smoothed the tablecloth twice.',['The kitchen smelled of cinnamon.','Outside, a dog barked at the bicycles going by.'],'Checking the clock again and again and smoothing the cloth are actions that show nervous waiting. The smell and the dog say nothing about how Mara feels.'],
 ['evidence','mara','Which inference is best supported by the passage?','Mara is waiting for something and feels uneasy about it.',['Mara is angry at her neighbor’s dog.','Mara has just finished eating and is bored.'],'An inference uses clues. Her clock-watching and fussing point to uneasy waiting; nothing in the passage points to anger at the dog or to boredom.'],
 ['evidence','theo','Which detail is the best evidence that Theo has been out in wet weather?','His boots were caked with mud and his sleeves were wet to the elbow.',['He held his palms to the stove.','He set the lantern down gently.'],'Mud and wet sleeves are physical signs of being outdoors in the wet. The stove and the lantern do not show where he has been.'],
 ['evidence','theo','Which of these is stated directly in the passage, not inferred?','Theo held his palms to the stove.',['Theo is worried that the river will flood.','Theo walked a long way to reach the house.'],'The passage says outright that he held his palms to the stove. His worry and his long walk are inferences a reader makes from clues.'],
 ['evidence','theo','Which of these is an inference, not something the passage states?','Theo is worried that the river may flood.',['Theo said the river was higher than it had been.','Theo’s boots were caked with mud.'],'The passage states what Theo said and what his boots looked like. That he is worried is the reader’s conclusion from his careful lantern, his silence and his words about the river.'],
 ['evidence','lena','What does the passage suggest about why Lena puts the ribbon back?','She cannot afford it but does not want to say so.',['The seller refused to sell it to her.','She has to leave to meet a friend.'],'She counts her coins twice, puts the ribbon back and then says it is “too plain anyway.” The word “anyway” sounds like an excuse. Nothing says the seller refused or that she has to meet anyone.'],
 ['evidence','lena','Which detail best supports the claim that Lena cannot afford the ribbon?','Lena counted her coins twice and put the ribbon back.',['The ribbon was blue.','The scene takes place at a market.'],'Counting coins and then putting the item back are actions about money. The ribbon’s color and the setting do not bear on the claim.'],
 ['evidence','lena','Which detail best supports the claim that Lena is careful with money?','She counted her coins twice.',['She was at the market.','The seller did not answer.'],'Counting coins twice shows care with money. Where she was and what the seller did do not show a trait of Lena’s.'],
 ['evidence',null,'A student claims, “The bridge opening was later than the mayor promised.” Which evidence is strongest? A reader knows the mayor promised May.','The barriers were still up in June, a month after the promised May opening.',['The mayor spoke about the bridge.','Many people use bridges.'],'Strong evidence is specific and ties directly to the claim. It names the promised date and the later date that shows the delay.'],
 ['evidence','frostEnd','Which line best supports the claim that the speaker will be talking about this choice at some time in the future?','I shall be telling this with a sigh',['Two roads diverged in a wood, and I—','I took the one less traveled by,'],'“I shall be telling this” uses the future tense. The other lines describe the choice itself in the past.'],
 ['evidence','frostEnd','Which claim is best supported by the last line, “And that has made all the difference”?','The speaker believes the choice changed the course of his life.',['The speaker has not yet reached the fork in the road.','The speaker never chose either road.'],'The line says the choice “has made all the difference,” so he is looking back and crediting the choice with a large effect. The poem has him choosing a road.'],
 ['evidence',null,'What does it mean to cite textual evidence for a claim about a story?','To support the claim with exact details or words from the text.',['To give your own opinion of the author.','To retell the whole story in your own words.'],'Citing evidence means pointing to the exact words or details in the text that back up the claim.'],
 ['evidence',null,'Which kind of evidence is strongest for a claim about a character’s trait?','A specific action or quotation that directly shows the trait.',['A guess about what the author felt while writing.','A short summary of the whole plot.'],'Direct, specific words or actions in the text show the trait; a guess about the author or a plot summary does not.'],
 ['evidence',null,'Which statement best describes an inference from a text?','A conclusion that follows from clues in the text plus what the reader already knows.',['A word-for-word quotation from the text.','A fact that the text states outright.'],'An inference is reasoned from clues. A quotation or an outright statement is not an inference.'],

 ['theme','lantern','Which statement best expresses the theme of the passage?','People may give up their own comfort to protect others.',['Storms are more dangerous at night.','Oil should be stored carefully.'],'A theme is a message about life or people that the whole story suggests. The keeper burns everything he owns so the boats come home, which points to protecting others at a personal cost.'],
 ['theme','lantern','Which detail from the passage most helps develop the theme?','The keeper burns his chairs, table and door rather than let the light go out.',['The lantern burned on a cliff.','The night was stormy.'],'Burning his own furniture shows what he gives up for the boats. The cliff and the storm are setting details.'],
 ['theme',null,'Which of these is a topic and not a theme?','Sacrifice',['Giving up something for others can show real care.','Hard times can bring out the best in people.'],'A topic is a subject, often a word or short phrase. A theme is a full statement about it.'],
 ['theme','sparrows','Which statement best expresses the theme of the passage?','Fighting over something can make everyone lose it.',['Crows are cleverer than sparrows.','Birds should never carry food.'],'The sparrows quarrel and a crow takes the crust. The message is about what quarreling costs.'],
 ['theme','sparrows','Which sentence is the best objective summary of the passage?','Two sparrows quarrel over a crust of bread, and while they fight, a crow takes it.',['The sparrows are foolish creatures, which makes this a silly story.','Two sparrows share a crust of bread and fly home together.'],'An objective summary reports the main events without opinions. One option gives an opinion, and another gets the events wrong.'],
 ['theme','ines','Which statement best expresses the theme of the passage?','Hiding the truth makes a problem heavier, and honesty brings relief.',['Report cards are unfair to students.','Families should not talk at dinner.'],'Ines’s lies pile up until she is silent, and telling the truth makes her feel lighter. That is the message the whole story builds.'],
 ['theme','ines','How does the author develop the theme as the story goes on?','Each lie adds to Ines’s burden until honesty finally lifts it.',['The setting changes from summer to winter and back again.','A new character arrives to solve Ines’s problem.'],'The theme grows through a pattern of events: more lies, a heavier burden, then relief when she tells the truth.'],
 ['theme','wolf','Which statement best expresses the theme of the passage?','People who lie lose trust, even when they later tell the truth.',['Shepherds should always carry a whistle.','Wolves are afraid of villagers.'],'No one believes the boy’s real cry because of his earlier false ones. That is the message about lying and trust.'],
 ['theme','wolf','Which sentence is a summary and not a theme?','A bored shepherd boy twice tricks the villagers with a false alarm, and when a real wolf comes no one helps him.',['Lies destroy trust.','Telling the truth matters most when others depend on you.'],'A summary retells the main events. The other two are messages that go beyond the events, so they are themes.'],
 ['theme','tortoise','Which statement best expresses the theme of the passage?','Steady effort can beat overconfidence.',['Hares should never run.','Races are won by luck alone.'],'The hare is sure of winning and naps, while the tortoise keeps going and wins. The message is about effort and overconfidence.'],
 ['theme','tortoise','Which detail most strongly develops the idea that overconfidence is risky?','The hare, sure of winning, lies down for a nap halfway through.',['The tortoise is slower than the hare.','The race has a finish line.'],'The hare’s overconfidence leads to the nap, and the nap costs him the race.'],
 ['theme',null,'Which of these is the strongest statement of a theme?','Courage means acting even when you are afraid.',['Courage','The hero is brave in chapter two.'],'A theme is a complete message. One word is only a topic, and one chapter’s event is only a plot detail.'],
 ['theme',null,'Two stories from different cultures both show a hero rewarded for kindness. What does this suggest?','Some themes appear in the literature of many cultures.',['One story must have copied the other directly.','Neither culture values kindness.'],'Similar themes can arise independently, so a shared theme says that people in many places care about the same ideas. It does not prove copying.'],
 ['theme',null,'Why should an objective summary leave out your opinions?','A summary reports what the text says, not what you think of it.',['Opinions are always wrong.','A summary should be as long as the original.'],'Summary and response are different jobs. A summary stays with the text.'],

 ['character','dev','What trait does Dev show in the passage?','He is considerate and welcoming.',['He is shy and afraid of strangers.','He is jealous of the new student.'],'He arrives early to help and offers his own tray to a student sitting alone. Those actions show care for others.'],
 ['character','dev','How does the author reveal Dev’s character?','Indirectly, through what he does and says.',['Directly, by stating his traits.','Through the setting around him.'],'The passage never names a trait. It shows Dev’s actions and words, which is indirect characterization.'],
 ['character','priya','How does the author reveal Priya’s character in this sentence?','Directly, by telling the reader a trait.',['Indirectly, through her actions.','Through what another character says.'],'The sentence tells us outright that she was stubborn. That is direct characterization.'],
 ['character','priya','The words “although she liked to call it determined” suggest what about Priya?','She sees her own stubbornness in a flattering way.',['She does not know what stubborn means.','She has no opinion of herself.'],'She prefers a kinder word for the same trait, which shows how she sees herself.'],
 ['character','owen','Is Owen a static or a dynamic character?','Dynamic, because he changes during the story.',['Static, because he never changes.','Static, because he is a minor character.'],'A dynamic character changes. Owen goes from refusing to speak to his brother to reaching out first.'],
 ['character','owen','What event does the passage connect to Owen’s change?','The flood, after which he helps his brother and apologizes.',['A letter from his brother, which he reads at dinner.','A new job in another town.'],'The passage says “after the flood” he carries the tools and says he is sorry. A letter and a job are not mentioned.'],
 ['character','nell','What kind of conflict does Nell face?','An internal conflict, a struggle with her own fear.',['An external conflict with another person.','An external conflict with the weather.'],'Nell wants to enter the race but is held back by fear. A conflict inside a character is internal.'],
 ['character','nell','Why does Nell hesitate at the sign-up table?','She fears failing in front of other people.',['She does not know where the table is.','She thinks the race is too short.'],'Her hands go cold and she imagines everyone watching her fail.'],
 ['character','cousins','What literary term describes how Ada’s character contrasts with Rosa’s?','Ada is a foil to Rosa.',['Ada is the narrator.','Ada is the setting.'],'A foil is a character whose contrasting traits highlight another character’s traits. Ada is careful where Rosa is reckless.'],
 ['character',null,'What is a foil in a story?','A character whose contrasts with another highlight the other’s traits.',['A character who narrates the story.','The main character’s goal.'],'A foil sets off another character by contrast.'],
 ['character','scrooge','How does Dickens characterize Scrooge in this line?','Directly: the narrator tells us he is tight-fisted.',['Indirectly: only through what Scrooge says aloud.','Through a description of the weather.'],'The narrator states the trait outright, which is direct characterization.'],
 ['character','scrooge','Which trait does the phrase “tight-fisted” point to?','Stinginess with money.',['Generosity with money.','Shyness in a crowd.'],'To be tight-fisted is to hold on to money and give little away.'],
 ['character','macbeth','What does Macbeth name as the driving force of his plans in these words?','Ambition',['Jealousy of a friend.','Fear of the dark.'],'In the speech he says that only “vaulting ambition” spurs him on.'],
 ['character',null,'In a story, what is the antagonist?','The character or force that opposes the protagonist.',['The narrator of the story.','The character who changes the most.'],'The antagonist is whoever or whatever stands against the main character.'],
 ['character',null,'How does a round character differ from a flat character?','A round character has many sides, with strengths and flaws.',['A round character never changes.','A round character is always the hero.'],'Round characters are complex and feel like real people; flat characters show one or two traits.'],
 ['character',null,'How can a character’s motivation move the plot forward?','What the character wants leads to choices that cause events.',['Motivation has no effect on events.','Motivation is only part of the setting.'],'Wants and fears lead characters to act, and their actions drive the plot.'],

 ['language','wordsworth','Which figure of speech is the comparison in this line?','Simile',['Metaphor','Personification'],'The line compares the speaker to a cloud with the word “as,” which makes it a simile.'],
 ['language','romeo','Which figure of speech is the comparison in this line?','Metaphor',['Simile','Hyperbole'],'Romeo says Juliet is the sun without “like” or “as,” so it is a metaphor.'],
 ['language','dickinson','In these lines, hope is compared to which living thing?','A bird',['A tree','A river'],'Hope is “the thing with feathers” that “perches,” which describes a bird.'],
 ['language','tyger','Which sound device repeats the opening consonant sound in “burning bright”?','Alliteration',['Onomatopoeia','Simile'],'The b sound repeats at the start of both words, which is alliteration.'],
 ['language','shadow','In these lines, life is compared to which of these?','A walking shadow and a poor actor.',['A calm sea.','A growing garden.'],'The lines call life “a walking shadow” and “a poor player” on a stage.'],
 ['language','shadow','What tone do these lines express?','Bleak and despairing.',['Joyful and hopeful.','Playful and teasing.'],'Calling life a shadow and a player who “frets his hour” and is then “heard no more” has a hopeless tone.'],
 ['language','raven','Which word in the line does most to create a gloomy mood?','dreary',['Once','upon'],'“Dreary” is a gloomy word. “Once” and “upon” carry no feeling.'],
 ['language','yellow','What does the adjective “yellow” help the reader picture?','A wood in autumn.',['A wood on fire.','A wood covered in snow.'],'Leaves turn yellow in autumn, so the color places the wood in that season and gives the scene a fall setting.'],
 ['language','austen','What is the tone of this famous opening sentence?','Ironic and gently humorous.',['Angry and bitter.','Sad and solemn.'],'The narrator states a grand “truth” about men and marriage in a mock-serious way, which gives the sentence a wry, ironic tone.'],
 ['language','oak','What does the metaphor “a sentinel” suggest the oak does?','Stands guard at the gate.',['Falls over in the wind.','Blocks the road forever.'],'A sentinel is a guard, so the oak seems to be watching over the gate.'],
 ['language','placid','In this sentence, what does “placid” most nearly mean?','calm',['angry','curious'],'The shouting did not trouble her, so “placid” must mean calm.'],
 ['language','meager','In this sentence, what does “meager” most nearly mean?','small in amount',['very large','extremely spicy'],'One boiled egg left the travelers hungry, so the meal was small.'],
 ['language',null,'A writer describes a person as thin. Which word has the most negative connotation?','scrawny',['slender','thin'],'Slender suggests grace, thin is neutral and scrawny suggests weakness or neglect.'],
 ['language',null,'A writer describes a person who asks many questions. Which word has the most positive connotation?','curious',['nosy','prying'],'Curious sounds admiring; nosy and prying sound critical.'],
 ['language','million','Which figure of speech is the phrase “a million times”?','Hyperbole',['Simile','Personification'],'A million is an exaggeration used for emphasis, which is hyperbole.'],
 ['language','house','Which figure of speech gives the house a human action?','Personification',['Simile','Hyperbole'],'A house cannot groan or sigh. Giving it those human actions is personification.'],
 ['language',null,'What is tone in a piece of writing?','The author’s attitude toward the subject.',['The order of the events.','The name of the speaker.'],'Tone is the writer’s attitude, such as bitter, playful or admiring. Mood is the feeling created in the reader.'],
 ['language','bread','What does the sentence mostly appeal to?','The sense of smell.',['The sense of sight.','The sense of hearing.'],'“Smelled of cinnamon and warm bread” is imagery that appeals to smell.'],

 ['structure','rafi','Which narrative device does this sentence use?','Flashback',['Foreshadowing','Cliffhanger'],'Rafi is carried back to a time when he was six, so the story steps back to an earlier moment.'],
 ['structure','step','Which narrative device does this passage use?','Foreshadowing',['Flashback','Simile'],'The warning about the cracked step hints at something that may happen later.'],
 ['structure','sonnet18','Which word at the end of a line rhymes with “day” in these four lines?','May',['temperate','date'],'Lines 1 and 3 end in “day” and “May.” Lines 2 and 4 end in “temperate” and “date,” which rhyme with each other.'],
 ['structure',null,'How many lines does a sonnet have?','14',['12','16'],'Both Shakespearean and Italian sonnets have fourteen lines.'],
 ['structure',null,'What do we call the two rhymed lines that end a Shakespearean sonnet?','A couplet',['A quatrain','An octave'],'A Shakespearean sonnet ends with a rhymed couplet; before it come three quatrains.'],
 ['structure',null,'How is an Italian (Petrarchan) sonnet usually divided?','An octave of eight lines and a sestet of six.',['Three quatrains and a couplet.','Seven couplets.'],'The Italian sonnet is usually built from an octave and a sestet; three quatrains and a couplet describe the Shakespearean form.'],
 ['structure','frostOne','How many lines are in this stanza?','Five',['Four','Six'],'Count the lines of the printed stanza: it has five lines, not the four of a quatrain.'],
 ['structure','frostOne','Which end word in this stanza rhymes with “wood”?','stood',['both','undergrowth'],'“Wood,” “stood” and “could” end lines 1, 3 and 4 and rhyme.'],
 ['structure',null,'At which point in a plot does the conflict reach its highest tension?','Climax',['Exposition','Resolution'],'The climax is the turning point or peak of the conflict.'],
 ['structure',null,'Which part of a plot introduces the setting, the characters and the basic situation?','Exposition',['Climax','Falling action'],'The exposition sets up the story: it tells who the characters are, where and when it happens, and what the situation is.'],
 ['structure',null,'What does it mean to say a story begins in medias res?','It starts in the middle of the action.',['It starts with a long description of the setting.','It starts by telling the end.'],'In medias res is Latin for into the middle of things.'],
 ['structure','storm','What does the author do with time in this passage?','Speeds it up by summarizing days.',['Slows it down to show every second.','Reverses it with a flashback.'],'Three days and a week pass in two sentences, so the pace is fast.'],
 ['structure','key','Why might the author use short sentences and slow detail here?','To build suspense by slowing the moment.',['To skip over years quickly.','To list facts about the house.'],'Short sentences and small steps stretch the moment out and raise tension.'],
 ['structure',null,'Why might an author keep a key fact hidden until the end of a story?','To create suspense or a surprise.',['To make the plot easier to guess.','To avoid writing a climax.'],'Holding back information keeps the reader guessing and can make the reveal land harder.'],
 ['structure','dickens','What structure does this opening use?','Parallel structure that sets opposites side by side.',['A flashback to an earlier year.','A rhyme scheme.'],'Two matching clauses, “best” and “worst,” balance each other and stress the contrast.'],
 ['structure',null,'What is a frame story?','A story that surrounds and introduces other stories.',['A story with no ending.','A story told only in poetry.'],'A frame story gives the setting in which other tales are told.'],
 ['structure',null,'What is a stanza in a poem?','A group of lines set apart from other groups.',['A single rhymed word.','The title of the poem.'],'A stanza is to a poem roughly what a paragraph is to prose.'],

 ['pov','first','Which point of view does this passage use?','First person',['Third person limited','Third person omniscient'],'The narrator is “I,” a character in the story.'],
 ['pov','limited','Which point of view does this passage use?','Third-person limited',['First person','Third-person omniscient'],'The narrator stays outside the story but reports only Marisol’s thoughts.'],
 ['pov','omni','Which point of view does this passage use?','Third-person omniscient',['First person','Third-person limited'],'The narrator reveals the thoughts of Jon, his sister and their mother.'],
 ['pov','liar','What makes the narrator seem unreliable?','What he says about himself does not match what he does.',['He tells the story in the past tense.','He uses the word “I.”'],'He says he is calm, but his hands shake and he drops the cup. An unreliable narrator tells the story in a way the reader cannot fully trust.'],
 ['pov',null,'In a play, the audience knows a friend is a traitor, but the hero does not. What is this called?','Dramatic irony',['Foreshadowing','A soliloquy'],'Dramatic irony is when the audience knows more than a character does.'],
 ['pov',null,'A fire station burns down. Which kind of irony is this?','Situational irony',['Verbal irony','Dramatic irony'],'The outcome is the opposite of what we expect, which is situational irony.'],
 ['pov',null,'On a day of freezing rain, a character says, “What lovely weather!” What is this?','Verbal irony',['Situational irony','A simile'],'The character says the opposite of what is meant, which is verbal irony.'],
 ['pov','ayele','What does the passage reveal about the village’s culture?','It values respect for elders and hospitality to guests.',['It has no customs about meals.','It treats guests with suspicion.'],'The oldest person washes first and every guest is offered salt bread.'],
 ['pov','bell','What does the festival custom suggest about the town?','It values the young and the future.',['It fears children.','It has no festivals.'],'The youngest child rings the last bell because the town thinks the future should have the last word.'],
 ['pov',null,'How can reading literature from another culture help a reader?','It can show values and experiences different from the reader’s own.',['It proves all cultures are the same.','It makes close reading unnecessary.'],'World literature opens other points of view and customs.'],
 ['pov','wren','What effect does a child narrator who misreads the adults’ actions create?','The reader understands more than the narrator, which creates irony.',['The reader knows less than the narrator.','The narrator cannot see anything.'],'We guess that the men are making a list of the family’s belongings, which Wren does not understand.'],
 ['pov',null,'How does a narrator’s point of view affect what a reader learns?','Events are filtered through one person’s knowledge, feelings and biases.',['Events happen in a different order.','Events never happened.'],'We see only what the narrator knows or chooses to tell.'],
 ['pov',null,'What is one effect of telling a story from the villain’s point of view?','The reader may come to understand or even sympathize with the villain.',['The reader learns nothing about the villain.','The villain becomes a minor character.'],'Seeing events through the villain’s eyes can make his reasons seem human.'],
 ['pov',null,'Which pronouns signal first-person narration?','I, me and my',['he, him and his','you and your'],'A first-person narrator is a character in the story who speaks as “I” or “we,” so the pronouns I, me and my give it away.'],

 ['media',null,'A novel describes a character’s fear in a long paragraph. A film shows the same fear with a long close-up of trembling hands and no dialogue. What does the film do?','It shows the feeling through images instead of description.',['It leaves the feeling out.','It tells the feeling through a narrator’s paragraph.'],'A close-up carries meaning through a picture where the novel uses words.'],
 ['media',null,'What is a soliloquy?','A speech in which a character alone on stage speaks his thoughts aloud.',['A short song between scenes.','A speech given to the whole cast.'],'A soliloquy lets the audience hear a character’s private thoughts.'],
 ['media',null,'Hamlet’s speech beginning “To be, or not to be” is a soliloquy. What does a soliloquy let the audience know?','The character’s private thoughts.',['The next scene’s setting.','What the other characters think.'],'A soliloquy opens a character’s thoughts to the audience.'],
 ['media','bear','What does this stage direction tell the performers to do?','Leave the stage while a bear chases after.',['Enter carrying a bear.','Speak to a bear.'],'“Exit” means leave the stage; “pursued by a bear” says what follows.'],
 ['media',null,'What are stage directions in a play script?','Notes that tell actors and directors about movement, setting and sound.',['Lines spoken aloud by the narrator.','The title and author.'],'Stage directions guide the performance, not the dialogue.'],
 ['media','juliet','Both stagings show “It is the east, and Juliet is the sun.” Which detail most directly makes the audience see Juliet as a source of light?','The single spotlight on Juliet.',['The soft music.','The city lights behind the window.'],'A spotlight on her makes her the source of light on stage.'],
 ['media',null,'Which of these can most easily show what a character thinks without anyone saying it aloud?','A novel whose narrator describes the thoughts.',['A silent photograph.','A museum label.'],'A narrator can describe thoughts directly, which is easier on the page than in a still image.'],
 ['media',null,'A film adaptation cuts a subplot from the novel. What is the most likely reason?','To fit the story into a shorter running time.',['To make the story longer.','Because films cannot have subplots.'],'Filmmakers often trim a long book to fit about two hours.'],
 ['media',null,'What is an adaptation?','A version of a work retold in a different form or medium.',['A summary written for a test.','A review of a work.'],'A film of a novel is an adaptation: the same story retold in a different medium, with its own choices.'],
 ['media','mina','How does the stage version convey the same idea as “We go on”?','Through a silent action instead of words.',['By adding a narrator to explain.','By removing the grandmother.'],'Hanging up the coat shows she is carrying on without saying so.'],
 ['media',null,'Which question helps you compare a play script with a filmed version?','What did the film add, change or leave out?',['How many tickets were sold?','Who owns the theater?'],'Comparing means looking at what is emphasized or missing in each version.'],
 ['media',null,'In a film scene, soft strings play as a character walks into an empty house. What might the music add?','A sad or uneasy mood.',['A list of the character’s traits.','The address of the house.'],'Music shapes mood: soft strings in an empty house make a viewer feel sadness or unease before anything happens.'],
 ['media',null,'A film shows a tiny figure crossing a huge empty field. What might this long shot suggest?','The character is small, isolated or alone.',['The character is very powerful.','The character has many close friends.'],'A wide shot with a small figure often suggests loneliness.'],
 ['media',null,'Why can two productions of the same play differ even when the words are the same?','Directors and actors make choices about tone, setting and staging.',['The words change every night.','Plays are never meant to be performed.'],'Plays are written to be performed; each production interprets the words.'],
 ['media',null,'Why do some productions of Shakespeare’s plays set the story in a modern time?','To help a new audience see the play’s ideas in a fresh setting.',['Because the original words are lost.','Because Shakespeare required it.'],'Directors choose a setting to bring out themes for an audience.'],

 ['allusion',null,'In literature, what is a character’s “Achilles’ heel”?','A weakness that can lead to downfall.',['A hidden strength.','A talent for running.'],'In the Greek myth, Achilles could be wounded only in his heel.'],
 ['allusion',null,'The phrase “Achilles’ heel” comes from which tradition?','Greek mythology',['The Bible','The plays of Shakespeare'],'Achilles is a hero of Greek myth and of Homer’s Iliad.'],
 ['allusion',null,'To “open Pandora’s box” means to do what?','Start something that brings many unforeseen troubles.',['Solve a puzzle quickly.','Give a generous gift.'],'In the Greek myth, Pandora opened a jar that released troubles into the world.'],
 ['allusion',null,'Someone said to have “the Midas touch” is thought to be what?','Able to turn almost anything into money.',['Afraid of gold.','Bad at business.'],'King Midas, in Greek myth, turned what he touched into gold.'],
 ['allusion',null,'A salesperson’s “free gift” hides a costly contract, and a reviewer calls it a Trojan horse. What does the allusion suggest?','An offer that looks harmless but hides danger.',['A gift that is very large.','A fast delivery.'],'In the story of the Trojan War, Greek soldiers hid inside a wooden horse that the Trojans took into their city.'],
 ['allusion',null,'Calling someone “a Scrooge” alludes to Dickens’s A Christmas Carol. What does it suggest?','The person is a stingy miser.',['The person is very generous.','The person is always cheerful.'],'Scrooge begins Dickens’s story as a miser, so calling someone a Scrooge alludes to that stingy character.'],
 ['allusion',null,'Calling a stranger who helps an injured traveler “a good Samaritan” alludes to which source?','A parable in the Gospel of Luke.',['Homer’s Odyssey.','Shakespeare’s Hamlet.'],'Jesus tells the parable of the Good Samaritan in the Gospel of Luke.'],
 ['allusion',null,'A young man wastes his money, returns home and is forgiven. Which Bible parable does this recall?','The prodigal son',['The Tower of Babel','Pandora’s box'],'The parable of the prodigal son, in Luke, tells this story.'],
 ['allusion',null,'A commentator calls a small team’s win over a champion “David and Goliath.” What does the allusion convey?','A weaker underdog defeats a stronger opponent.',['Two equal rivals tie.','A giant wins easily.'],'In the Bible, the young David defeats the giant Goliath.'],
 ['allusion',null,'A novel’s character rises too high and falls “like Icarus.” What does the allusion suggest?','Overreaching ambition can lead to a fall.',['Careful planning leads to success.','Flight is easy.'],'In Greek myth, Icarus flew too near the sun, and the wax holding his wings melted.'],
 ['allusion',null,'Calling a young man “a Romeo” alludes to Shakespeare’s Romeo and Juliet. What does it suggest?','He is a passionate romantic lover.',['He is a fierce soldier.','He is a clever thief.'],'Romeo is the young lover in Shakespeare’s play.'],
 ['allusion',null,'The 1957 musical West Side Story retells Romeo and Juliet. How does it transform the source?','It sets the feuding families as rival street gangs in New York City.',['It keeps Verona and the Montagues and Capulets exactly.','It removes the love story.'],'The musical keeps the star-crossed love and the feud but moves them to 1950s New York.'],
 ['allusion',null,'The play within a play “Pyramus and Thisbe” in Shakespeare’s A Midsummer Night’s Dream draws on which earlier source?','The Roman poet Ovid’s Metamorphoses.',['The Gospel of Luke.','The novels of Charles Dickens.'],'Ovid, writing in Latin about two thousand years ago, tells the story of Pyramus and Thisbe in his Metamorphoses.'],
 ['allusion',null,'Many cultures tell flood stories, such as the Epic of Gilgamesh and the Bible’s story of Noah. What can a writer do by alluding to a flood story?','Link a story to an old, widely known theme such as destruction and renewal.',['Prove that the story is true.','Avoid having a theme.'],'An allusion borrows the weight of a well-known story.'],
 ['allusion',null,'James Joyce’s novel Ulysses (1922) follows one day in Dublin and echoes which ancient work?','Homer’s Odyssey',['The Epic of Gilgamesh','Beowulf'],'Joyce built parallels to the Odyssey; Ulysses is the Latin name of Odysseus.'],
 ['allusion',null,'A task called “Sisyphean” is one that is what?','Endless and seemingly pointless.',['Done very quickly.','Always done by a group.'],'In Greek myth, Sisyphus must push a boulder uphill, and it rolls back down again and again.']];
/* The Try-it questions in pool form; the generator skips them. */
const TRY=['Fictional passage: “Sam’s backpack hung open, and three pencils lay on the stairs behind him. He did not stop to pick them up. ‘Don’t wait for me!’ he called, taking the steps two at a time.” Which of these is an inference, not something the passage states? A: Sam called to someone, B: Sam is late, C: Pencils lay on the stairs. Answer A, B or C.',
 'Fictional passage: “The moon was a silver coin dropped in the dark lake.” Which figure of speech is this? A: Simile, B: Metaphor, C: Personification. Answer A, B or C.',
 'Fictional passage: “We packed the car before dawn, and I held the map.” Which point of view does this passage use? A: First person, B: Third-person limited, C: Third-person omniscient. Answer A, B or C.',
 'A writer says a character has “a Cassandra’s fate” in a story of warnings no one believes. In Greek myth, Cassandra is a prophet. What does the allusion suggest? A: She warns of danger but no one believes her, B: She becomes very wealthy, C: She wins a great race. Answer A, B or C.'];
const tryIt=s=>`Try it: ${s[0].toLowerCase()+s.slice(1)}`;
export default {
id:'language-h-english-9-reading-literature',subject:'language',level:5,grade:9,standard:'CCSS ELA Reading: Literature, RL.9-10.1 to 9-10.7 and 9-10.9',
title:'Reading Literature',
goal:'Read stories, poems and plays closely: cite the words that prove a claim, state a theme and summarize without opinion, explain how characters, word choices, structure and point of view build meaning, compare a text with another medium, and recognize allusions.',
points:20,
skills:{evidence:'Textual evidence',theme:'Theme and summary',character:'Characters',language:'Words, figures of speech, tone',structure:'Structure',pov:'Point of view and world literature',media:'Another medium',allusion:'Allusions and sources'},
outline:[['RL.9-10.1','Cite strong and thorough textual evidence',['evidence']],['RL.9-10.2','Determine a theme and write an objective summary',['theme']],['RL.9-10.3','Analyze complex characters',['character']],['RL.9-10.4','Determine word meaning, figurative language, tone and mood',['language']],['RL.9-10.5','Analyze how structure shapes meaning',['structure']],['RL.9-10.6','Analyze point of view and cultural experience in world literature',['pov']],['RL.9-10.7','Analyze a subject in two artistic mediums',['media']],['RL.9-10.9','Analyze how an author draws on and transforms source material',['allusion']]],
steps:[
 {skill:'evidence',say:'Reading literature closely starts with evidence. A claim is a statement about the text, and strong evidence is the exact word or detail that proves it. Here the claim is about a character, and the quotation that shows an action ties directly to it, while the sentence about the weather does not.',pic:board('From claim to evidence',['Claim: Idris is worried.','Text: “Idris read the note again, twice.”','Link: rereading shows worry','Not evidence: “It was a cloudy day.”'],['what we want to prove','the exact words','why it proves the claim','true, but about the weather'])},
 {skill:'evidence',say:'Separate what a text states from what a reader infers. The text states that Sam’s pencils lay on the stairs. The reader infers that Sam is hurrying, because he did not stop and took the steps two at a time. An inference is a conclusion drawn from clues in the text plus what you already know, and you should be able to point to those clues.',pic:board('Stated or inferred?',['Stated: “He did not stop to pick them up.”','Clue: he took the steps two at a time','Inference: he is in a hurry','Check: can I point to the clue?'],['the text says it outright','what the text shows','what the reader concludes','an inference needs a clue']),
  check:{prompt:tryIt(TRY[0]),answer:'B',options:['A','B','C'],hint:'The passage says he called to someone and that pencils lay on the stairs. Which choice does it never say outright?',pic:pass('Fictional passage',['Sam’s backpack hung open, and three pencils lay on the stairs behind him.','He did not stop to pick them up.','“Don’t wait for me!” he called, taking the steps two at a time.'])}},
 {skill:'theme',say:'A topic is a subject, such as friendship or honesty. A theme is a message about that subject, written as a full statement, such as honesty keeps trust alive. A theme is not a plot detail and not a single word. It is built from the whole story, so look for what the main character learns or loses.',pic:flow('From topic to theme',[['Topic','One word: honesty'],['What happens','A character lies, then is trusted less'],['Theme','Lies cost trust']])},
 {skill:'theme',say:'A summary and a theme are different jobs. An objective summary tells the main events in your own words and leaves out your opinions. A theme goes beyond the events to a message. Details develop a theme by repeating a pattern, such as a character who keeps being rewarded for generosity, until the message is clear.',pic:board('Summary or theme?',['Summary: A girl returns a wallet.','Theme: Honesty can bring good things.','Not summary: “This is boring.”'],['events only','a message','an opinion'])},
 {skill:'character',say:'Authors reveal characters in two ways. Direct characterization tells you a trait in so many words, as when a narrator says a man was greedy. Indirect characterization shows the trait through the character’s actions, words, thoughts and what others say or do. Most stories rely mainly on indirect characterization, so you must infer the trait from the evidence.',pic:board('Two ways to show a trait',['Direct: “Lars was generous.”','Indirect: Lars shared his last apple with a stranger.','Ask: what does the action show?'],['the narrator tells','the action shows','infer the trait'])},
 {skill:'character',say:'Complex characters want things, face conflicts and sometimes change. A dynamic character changes during the story, while a static character stays the same. A foil is a character who contrasts with another, such as a calm friend beside a reckless one, and the contrast highlights both. Follow what a character wants, what stands in the way, and what the character does about it.',pic:flow('A character’s path',[['Wants','A goal or a fear'],['Choices','Actions that cause events'],['Change','Dynamic or static']])},
 {skill:'language',say:'Figurative language says one thing in terms of another. A simile compares with the words like or as, as in Robert Burns’s line “O my Luve’s like a red, red rose.” A metaphor says one thing is another, with no like or as. Personification gives a human action to a thing, and hyperbole exaggerates for emphasis. Ask what the comparison makes you see or feel.',pic:pass('Robert Burns, “A Red, Red Rose” (1794), first line',['O my Luve’s like a red, red rose','Simile: the comparison uses “like.”'],false)},
 {skill:'language',say:'Tone is the writer’s attitude toward the subject, such as admiring, bitter or playful. Mood is the feeling the writing creates in the reader, such as calm or uneasy. Both come from word choice. Words with the same meaning can carry different connotations: slender sounds graceful while scrawny sounds weak, so choose the word that fits the writer’s attitude.',pic:board('Tone and mood',['Tone: the writer’s attitude','Mood: the reader’s feeling','Connotation: slender, thin, scrawny','Evidence: the exact words chosen'],['bitter, playful, admiring','calm, uneasy, hopeful','three words, three feelings','quote the words that show it']),
  check:{prompt:tryIt(TRY[1]),answer:'B',options:['A','B','C'],hint:'The sentence says the moon was a coin. Does it use like or as, or give the moon a human action?',pic:pass('Fictional passage',['The moon was a silver coin dropped in the dark lake.'],false)}},
 {skill:'structure',say:'Plots are often described in five parts. The exposition sets the scene and the characters. The rising action builds the conflict. The climax is the peak of tension. The falling action follows, and the resolution settles the conflict. An author chooses the order, and a flashback, foreshadowing or a story that begins in medias res changes how a reader feels.',pic:pyramid},
 {skill:'structure',say:'Poems have structure too. A stanza is a group of lines, and a Shakespearean sonnet has fourteen lines in three quatrains and a final couplet, with the rhyme scheme ABAB CDCD EFEF GG. A sonnet’s last couplet often turns or sums up the idea. Notice how the shape of a text helps carry its meaning.',pic:board('A Shakespearean sonnet',['Quatrain 1: ABAB','Quatrain 2: CDCD','Quatrain 3: EFEF','Couplet: GG'],['four lines','four lines','four lines','two lines, often a turn'])},
 {skill:'pov',say:'Point of view decides who tells the story and what the reader can know. A first-person narrator is a character who says I. A third-person limited narrator stays close to one character’s thoughts. A third-person omniscient narrator knows the thoughts of many. Ask whose knowledge and feelings shape what you read, and whether the narrator can be trusted.',pic:board('Who is telling it?',['First person: “I opened the door.”','Third limited: “She opened the door and feared what waited.”','Omniscient: “She feared what waited, and he hoped.”','Trust: does the narrator know and tell the truth?']),
  check:{prompt:tryIt(TRY[2]),answer:'A',options:['A','B','C'],hint:'Look at the pronouns we and I in the passage.',pic:pass('Fictional passage',['We packed the car before dawn, and I held the map.'],false)}},
 {skill:'pov',say:'Irony happens when what is meant or expected is not what is said or happens. In verbal irony a speaker says the opposite of what is meant. In situational irony an event is the opposite of what we expect. In dramatic irony the audience knows more than a character does. World literature also shows customs and values from outside the United States, so read for what a work shows about its own culture.',pic:flow('Three kinds of irony',[['Verbal','Says the opposite'],['Situational','Outcome is unexpected'],['Dramatic','Reader knows more']])},
 {skill:'media',say:'A story told in two mediums is not the same story twice. A novel can describe thoughts in words, a play depends on actors, a stage and soliloquies, and a film uses camera angles, close-ups and music. When you compare a text with a staging or film, ask what each emphasizes and what each leaves out, and why the artist might have chosen it.',pic:board('Same story, different tools',['Novel: narrator describes thoughts','Play: actors, stage, soliloquy','Film: camera, close-up, music','Compare: what is added, changed or left out?'],['words on a page','a live performance','images and sound','the key question'])},
 {skill:'media',say:'Choices in staging change the meaning a viewer receives. A single spotlight on a character tells the audience where to look, soft strings make a quiet room feel sad, and a very wide shot of one figure can suggest loneliness. Two productions can use the same words and still emphasize different ideas, because directors and actors interpret the script.',pic:pass('Fictional staging choices',['A spotlight: where to look.','Soft strings: a sad or uneasy mood.','A very wide shot: isolation.'],false)},
 {skill:'allusion',say:'An allusion is a short reference to a well-known story, person or work, such as Achilles’ heel from Greek myth, a Scrooge from Dickens or a good Samaritan from the Bible. It lets a writer borrow the meaning of the old story in a few words. To read an allusion, name its source and ask what it adds to this text.',pic:flow('How an allusion works',[['Old story','Myth, Bible, play, novel'],['Short phrase','A few words recall it'],['New meaning','Adds weight to the text']]),
  check:{prompt:tryIt(TRY[3]),answer:'A',options:['A','B','C'],hint:'The story is about warnings no one believes. Which choice matches?',pic:tab('Cassandra',[['source','Greek myth'],['her fate','warns, but is not believed']])}},
 {skill:'allusion',say:'Authors also transform source material. Shakespeare drew on earlier stories for many plots, and a later artist can reshape his. The musical West Side Story, first staged in 1957, keeps the feud and the love of Romeo and Juliet but moves them to rival street gangs in New York. Compare what stays and what changes, and ask what the change shows.',pic:{t:'timeline',events:['about 1595: Romeo and Juliet','1957: West Side Story']}},
 {skill:'allusion',summary:true,say:'Tie the unit together with one habit: read closely, then prove it. State a claim, find the exact words that support it, and explain how the writer’s choices of character, language, structure, point of view and source build the meaning. Check that your evidence fits the claim, that a theme is a full statement, and that a summary keeps opinion out.',pic:flow('Reading literature: the habit',[['Read closely','Notice the words'],['Prove it','Quote the evidence'],['Explain','How the choices build meaning']])}],
progression:{requires:['language-m-claims-evidence','language-m-connotation','language-e-point-of-view','language-e-similes-metaphors'],operations:2,demand:'Read short stories, poems and plays closely: back a claim with the exact words, state a theme and an objective summary, name how characters, figures of speech, structure, point of view and other media shape meaning, and recognize allusions.'},
items(add){
 const seen=new Set(TRY);
 const put=(skill,prompt,answer,pic,explanation,accept)=>{if(seen.has(prompt))return;seen.add(prompt);add(skill,prompt,answer,pic,explanation,accept);};
 ROWS.forEach(([skill,key,q,right,wrong,why],k)=>{const c=choose(right,wrong,k);
  if(!key){put(skill,`${q} ${c.text}. ${ask(c.n)}`,c.letter,null/* 25 Oct: no picture; it only repeated the question in tiny type */,why,[right,dot(right)]);return;}
  const [src,lines,verse]=P(key),text=lines.join(verse?' / ':' ');
  put(skill,`${src}: “${text}” ${q} ${c.text}. ${ask(c.n)}`,c.letter,pass(src,lines),why,[right,dot(right)]);});
}};
